function adminiTheme_output($vars)
{
    require_once ROOTDIR . "/modules/addons/adminiTheme/classes/adminiTheme.class.php";
    define("MODURL", $vars["modulelink"]);
    define("MODVERION", $vars["version"]);
    global $CONFIG;
    global $templates_compiledir;
    // $licenseresult = mysql_query("select * from coodiv__control__panel__license where itemid= '52246062'");
    // $licenseactivated = mysql_num_rows($licenseresult) ? true : false;
    $licenseactivated = true;
    $smarty = new Smarty();
    $smarty->setCompileDir($templates_compiledir);
    $smarty->setTemplateDir(ROOTDIR . "/modules/addons/adminiTheme/views/");
    $smarty->compile_id = md5(MODURL);
    $menu = new adminiTheme();
    $menu->displayTranslation = false;
    $_LANG = $menu->loadLanguageFile();
    $smarty->assign("_LANG", $_LANG);
    $templateFile = "groups.tpl";
    $license__check__pages = "license.tpl";
    $smarty->assign("modPageTitle", "AdminiTheme Control Panel");
    $smarty->assign("modurl", MODURL);
    $menu->addToBreadCrumbs(MODURL, "AdminiTheme Control Panel");
    $action = trim($_GET["action"]);
    $smarty->assign("action", $action);
    $languages = $menu->getWHMCSLanguages();
    $smarty->assign("languages", $languages);
    $smarty->assign("totallanguages", count($languages));
    $menu->allAccessLevel = ["1" => "Always enabled", "2" => "Displayed for visitors only", "3" => "Displayed for clients only"];
    if ($action == "") {
        $getGroups = Illuminate\Database\Capsule\Manager::table("coodiv__control__panel__license")->orderBy("id", "desc")->get();
        $groups = $menu->fromMYSQL($getGroups);
        $smarty->assign("groups", $groups);
    } else {
        if ($action == "homepage") {
            $templateFile = "homepage.tpl";
            $getGroups = Illuminate\Database\Capsule\Manager::table("coodiv__control__panel__license")->orderBy("id", "desc")->get();
